3050	// 本机请求重放与响应差异报告（replay 子命令）
3051	// ---------------------------------------------------------------------------
3052	//
3053	// 读取 GET /__contractlab/requests 的完整 JSON 快照，按输入顺序保留原编号，
3054	// 把每条记录的原始请求逐条重放到 127.0.0.1 的指定端口：前一条结束才发下一条，
3055	// 每次执行每条只尝试一次，不跟随重定向。仅比较实际响应的状态码与正文和记录
3056	// 中的计划响应（计划正文按 UTF-8 编码）；可选 --strategy 比较策略按
3057	// “方法 + 字面路径”为接口选择正文 JSON 语义比较（见下），未选中的接口仍按
3058	// 正文原始字节比较。不比较响应头，也不依据记录版本与发送状态判定——
3059	// pending / sent / interrupted 均可重放，400/404/500 同样按内容比较。
3060	// 不监听端口、不修改文件；已发送的请求可能已被目标处理，不重载、清空或
3061	// 回滚目标状态。
3062	//
3063	// 仅重放 GET/POST；target 须为以 "/" 开头的合法 HTTP 请求目标，原样发送
3064	// （保留查询串与百分号编码，不归一化路径）；禁止重放 /__contractlab 本身及
3065	// /__contractlab/ 前缀路径。每条记录另须有 200–599 的计划响应状态与文本正文。
3066	// 参数与全部记录（含可发送的头名称和值）有效后才连接；参数或快照失败退出 2，
3067	// stderr 给原因，stdout 为空且不发任何请求。
3068	//
3069	// 每条请求的总超时自开始连接覆盖完整收发，持续来数据也不延长；连接失败、
3070	// 超时或响应中途断开记通信失败，关闭连接后继续下一条（部分响应不算完整）。
3071	
3072	// 重放时剥离的头（小写）：原 Host / Expect / HTTP 逐跳与分帧头；
3073	// Connection 头指名的头名也一并剥离。Host 与 Content-Length 按目标和实际
3074	// 字节数重建。
3075	const REPLAY_STRIP_HEADERS: ReadonlySet<string> = new Set([
3076	  'host',
3077	  'expect',
3078	  'connection',
3079	  'keep-alive',
3080	  'content-length',
3081	  'transfer-encoding',
3082	  'te',
3083	  'trailer',
3084	  'upgrade',
3085	  'proxy-authenticate',
3086	  'proxy-authorization',
3087	]);
3088	
3089	// 一条待重放的请求：共享快照校验之上再经重放专用校验
3090	interface ReplayRequest {
3091	  readonly id: number;
3092	  readonly method: 'GET' | 'POST';
3093	  // 原样发送的请求目标（含查询串与百分号编码，不归一化）
3094	  readonly target: string;
3095	  // target 去掉查询串后的字面路径（比较策略按“方法 + 路径”选择接口）
3096	  readonly path: string;
3097	  // 过滤后的业务头：名称大小写、重复项与在线顺序原样保留
3098	  readonly headers: readonly [string, string][];
3099	  readonly body: Buffer;
3100	  readonly plannedStatus: number;
3101	  readonly plannedBody: string;
3102	}
3103	
3104	// target 须为以 "/" 开头的合法 HTTP 请求目标：不含空白与控制字符，
3105	// 且每个字符都在 Latin-1 内（与 Node 客户端对 path 的接受范围一致）
3106	function validateReplayTarget(target: string, where: string): void {
3107	  if (target.length === 0 || !target.startsWith('/')) {
3108	    snapshotFail(where, `必须是以 "/" 开头的 HTTP 请求目标，收到 ${JSON.stringify(target)}`);
3109	  }
3110	  for (const ch of target) {
3111	    const code = ch.charCodeAt(0);
3112	    if (code <= 0x20 || code === 0x7f) {
3113	      snapshotFail(where, `含空白或控制字符，不是合法的 HTTP 请求目标：${JSON.stringify(target)}`);
3114	    }
3115	    if (code > 0xff) {
3116	      snapshotFail(where, `含 Latin-1 之外的字符，无法作为 HTTP 请求目标发送：${JSON.stringify(target)}`);
3117	    }
3118	  }
3119	}
3120	
3121	// 过滤并校验待发送的业务头：剥离 Host/Expect/逐跳/分帧头（含 Connection
3122	// 指名的头），其余按原顺序、大小写与重复项保留；保留的头名称与值必须可发送。
3123	function filterReplayHeaders(
3124	  rawHeaders: readonly string[],
3125	  where: string,
3126	): [string, string][] {
3127	  const connectionNamed = new Set<string>();
3128	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
3129	    if ((rawHeaders[j] as string).toLowerCase() === 'connection') {
3130	      for (const token of (rawHeaders[j + 1] as string).split(',')) {
3131	        const name = token.trim().toLowerCase();
3132	        if (name !== '') {
3133	          connectionNamed.add(name);
3134	        }
3135	      }
3136	    }
3137	  }
3138	  const out: [string, string][] = [];
3139	  for (let j = 0; j + 1 < rawHeaders.length; j += 2) {
3140	    const name = rawHeaders[j] as string;
3141	    const value = rawHeaders[j + 1] as string;
3142	    const lower = name.toLowerCase();
3143	    if (REPLAY_STRIP_HEADERS.has(lower) || connectionNamed.has(lower)) {
3144	      continue;
3145	    }
3146	    if (!HEADER_NAME_RE.test(name)) {
3147	      snapshotFail(`${where}[${j}]`, `不是可发送的 HTTP 头名称：${JSON.stringify(name)}`);
3148	    }
3149	    for (let k = 0; k < value.length; k += 1) {
3150	      const code = value.charCodeAt(k);
3151	      // 与响应头同一规则：允许水平制表符；拒绝换行及其余控制字符；仅 Latin-1
3152	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
3153	        snapshotFail(
3154	          `${where}[${j + 1}]`,
3155	          `头 ${JSON.stringify(name)} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
3156	        );
3157	      }
3158	    }
3159	    out.push([name, value]);
3160	  }
3161	  return out;
3162	}
3163	
3164	function parseReplayRecord(raw: unknown, index: number, seen: Set<number>): ReplayRequest {
3165	  const where = `records[${index}]`;
3166	  // 先完整经历与 verify 相同的快照校验（含 target/path 一致性与正文无损性）
3167	  const base = parseSnapshotRecord(raw, index, seen);
3168	
3169	  if (base.method !== 'GET' && base.method !== 'POST') {
3170	    snapshotFail(
3171	      `${where}.request.method`,
3172	      `仅支持重放 GET/POST，收到 ${JSON.stringify(base.method)}`,
3173	    );
3174	  }
3175	  validateReplayTarget(base.target, `${where}.request.target`);
3176	  if (base.path === ADMIN_BASE || base.path.startsWith(ADMIN_PREFIX)) {
3177	    snapshotFail(
3178	      `${where}.request.target`,
3179	      `指向管理入口（${ADMIN_BASE} 本身及 ${ADMIN_PREFIX} 前缀），禁止重放`,
3180	    );
3181	  }
3182	
3183	  // 每条记录另须有 200–599 的计划响应状态与文本正文（比较基准）
3184	  const prWhere = `${where}.plannedResponse`;
3185	  const planned = (raw as Record<string, unknown>).plannedResponse;
3186	  if (!isPlainObject(planned)) {
3187	    snapshotFail(prWhere, '必须是对象（重放需要计划响应状态与文本正文）');
3188	  }
3189	  const { status, body } = planned;
3190	  if (!Number.isInteger(status) || (status as number) < 200 || (status as number) > 599) {
3191	    snapshotFail(
3192	      `${prWhere}.status`,
3193	      `必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`,
3194	    );
3195	  }
3196	  if (typeof body !== 'string') {
3197	    snapshotFail(`${prWhere}.body`, '必须是文本字符串');
3198	  }
3199	  if (hasLoneSurrogate(body as string)) {
3200	    snapshotFail(
3201	      `${prWhere}.body`,
3202	      '含孤立代理项（lone surrogate）：按 UTF-8 编码会被替换字符改写，无法作为无损的比较基准',
3203	    );
3204	  }
3205	
3206	  return {
3207	    id: base.id,
3208	    method: base.method,
3209	    target: base.target,
3210	    path: base.path,
3211	    headers: filterReplayHeaders(base.rawHeaders, `${where}.request.rawHeaders`),
3212	    body: base.body,
3213	    plannedStatus: status as number,
3214	    plannedBody: body as string,
3215	  };
3216	}
3217	
3218	function parseReplaySnapshot(raw: unknown): ReplayRequest[] {
3219	  const seen = new Set<number>();
3220	  return snapshotRecordsOf(raw).map((rec, i) => parseReplayRecord(rec, i, seen));
3221	}
3222	
3223	// 读取 -> 解析 -> 校验并重建；任何一步失败都抛出含文件路径与可定位原因的错误
3224	async function loadReplaySnapshotFromFile(snapshotPath: string): Promise<ReplayRequest[]> {
3225	  let text: string;
3226	  try {
3227	    text = await readFile(snapshotPath, 'utf8');
3228	  } catch (e) {
3229	    throw new Error(`读取请求记录快照文件 ${snapshotPath} 失败：${describeError(e)}`);
3230	  }
3231	
3232	  let raw: unknown;
3233	  try {
3234	    raw = JSON.parse(text);
3235	  } catch (e) {
3236	    throw new Error(`请求记录快照文件 ${snapshotPath} 不是合法 JSON：${describeError(e)}`);
3237	  }
3238	
3239	  try {
3240	    return parseReplaySnapshot(raw);
3241	  } catch (e) {
3242	    throw new Error(`请求记录快照文件 ${snapshotPath} 校验失败：${describeError(e)}`);
3243	  }
3244	}
