3345	// 读取 -> 解析 -> 校验；任何一步失败都抛出含文件路径与可定位原因的错误
3346	async function loadStrategyFromFile(strategyPath: string): Promise<JsonCompareStrategy> {
3347	  let text: string;
3348	  try {
3349	    text = await readFile(strategyPath, 'utf8');
3350	  } catch (e) {
3351	    throw new Error(`读取比较策略文件 ${strategyPath} 失败：${describeError(e)}`);
3352	  }
3353	
3354	  let raw: unknown;
3355	  try {
3356	    raw = JSON.parse(text);
3357	  } catch (e) {
3358	    throw new Error(`比较策略文件 ${strategyPath} 不是合法 JSON：${describeError(e)}`);
3359	  }
3360	
3361	  try {
3362	    return parseCompareStrategy(raw);
