3820	interface ReplayResponse {
3821	  readonly status: number;
3822	  readonly body: Buffer;
3823	}
3824	
3825	type ReplayExchange =
3826	  | { readonly ok: true; readonly response: ReplayResponse }
3827	  | { readonly ok: false; readonly reason: string };
3828	
3829	// 重放单条请求：独立连接、只尝试一次、不跟随重定向；总超时自开始连接覆盖
3830	// 完整收发，不因持续来数据而延长。通信失败时关闭连接并返回原因。
3831	function replayOne(port: number, request: ReplayRequest, timeoutMs: number): Promise<ReplayExchange> {
3832	  return new Promise((resolve) => {
3833	    let settled = false;
3834	    const done = (outcome: ReplayExchange): void => {
3835	      if (!settled) {
3836	        settled = true;
3837	        clearTimeout(timer);
3838	        resolve(outcome);
3839	      }
3840	    };
3841	
3842	    // 业务头在前（原顺序/大小写/重复项），随后按目标与实际字节数重建
3843	    // Host 与 Content-Length；每条请求独立连接，响应结束后关闭。
3844	    const headers: string[] = [];
3845	    for (const [name, value] of request.headers) {
3846	      headers.push(name, value);
3847	    }
3848	    headers.push('Host', `127.0.0.1:${port}`);
3849	    headers.push('Content-Length', String(request.body.byteLength));
3850	    headers.push('Connection', 'close');
3851	
3852	    const req = http.request({
3853	      host: '127.0.0.1',
3854	      port,
3855	      method: request.method,
3856	      path: request.target, // 原样发送：保留查询串与百分号编码，不归一化
3857	      headers,
3858	      agent: false, // 不连接池化：一次一条，每条只尝试一次
3859	    });
3860	
3861	    // 总超时：覆盖连接建立与完整收发，持续来数据不延长
3862	    const timer = setTimeout(() => {
3863	      req.destroy();
3864	      done({ ok: false, reason: `超过总超时 ${timeoutMs}ms（自开始连接覆盖完整收发）` });
3865	    }, timeoutMs);
3866	
3867	    req.on('response', (res) => {
3868	      const chunks: Buffer[] = [];
3869	      res.on('data', (chunk: Buffer) => chunks.push(chunk));
3870	      res.on('end', () => {
3871	        done({
3872	          ok: true,
3873	          response: { status: res.statusCode ?? 0, body: Buffer.concat(chunks) },
3874	        });
3875	      });
3876	      res.on('aborted', () => {
3877	        done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
3878	      });
3879	      res.on('error', (e: unknown) => {
3880	        done({ ok: false, reason: `响应读取失败：${describeError(e)}` });
3881	      });
3882	      res.on('close', () => {
3883	        if (!res.complete) {
3884	          done({ ok: false, reason: '响应中途断开（部分响应不算完整）' });
3885	        }
3886	      });
3887	    });
3888	    req.on('error', (e: Error) => {
3889	      done({ ok: false, reason: `通信失败：${e.message}` });
3890	    });
3891	    req.end(request.body);
3892	  });
3893	}
3894	
3895	// 完整响应的无损 JSON 表示（与请求记录正文同一套编码规则）
3896	function replayResponseJson(response: ReplayResponse): {
3897	  status: number;
3898	  body: { encoding: 'utf-8' | 'base64'; content: string };
3899	} {
3900	  return { status: response.status, body: encodeBodyLosslessly(response.body) };
3901	}
3902	
3903	type ReplayResultEntry =
3904	  | {
