    let bodyError: string | undefined;
    const decoded = decodeUtf8Strict(response.body);
    const actual = decoded.ok ? parseSemanticJson(decoded.text) : decoded;
    if (!actual.ok) {
      bodyDiff = true;
      bodyError = `实际响应正文${actual.reason}，无法进行 JSON 语义比较`;
