test('空字段名与 __proto__ 作业务键、~0/~1 转义定位对齐数组', { timeout: 60_000 }, async (t) => {
  const target = await startTarget(t, {
    // 键为空字段名 ""，重排后字段变化
    'GET /api/empty': {
